<?php
require __DIR__.'/../config/db.php'; require __DIR__.'/../config/security.php'; require_admin();
$notice='';$error='';$uploadDir=__DIR__.'/../uploads';if(!is_dir($uploadDir))mkdir($uploadDir,0755,true);
function save_media(array $f,string $dir): ?string { if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if($f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Échec du téléversement.');if($f['size']>50*1024*1024)throw new RuntimeException('Fichier trop volumineux (50 Mo maximum).');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','video/mp4'=>'mp4','video/webm'=>'webm'];if(!isset($allowed[$mime]))throw new RuntimeException('Format refusé. Utilisez JPG, PNG, WEBP, MP4 ou WEBM.');$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Impossible de sauvegarder le fichier.');return 'uploads/'.$name;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='save'){ $id=(int)($_POST['id']??0);$title=trim($_POST['titre']??'');$desc=trim($_POST['description']??'');$type=$_POST['type']??'publicite';$media=$_POST['media_type']??'image';$url=trim($_POST['video_url']??'');$published=isset($_POST['publie'])?1:0;if($title==='')throw new RuntimeException('Le titre est obligatoire.');if(!in_array($type,['publicite','bande_annonce','actualite'],true)||!in_array($media,['image','video','youtube'],true))throw new RuntimeException('Type de contenu invalide.');$file=save_media($_FILES['media']??[],$uploadDir);if($media==='youtube' && !preg_match('~^(https?://)?(www\.)?(youtube\.com|youtu\.be)/~i',$url))throw new RuntimeException('Indiquez une URL YouTube valide.');if($id){$oldq=$pdo->prepare('SELECT fichier FROM contenus WHERE id=?');$oldq->execute([$id]);$old=$oldq->fetch();if(!$old)throw new RuntimeException('Contenu introuvable.');$file=$file??$old['fichier'];$q=$pdo->prepare('UPDATE contenus SET titre=?,description=?,type=?,media_type=?,fichier=?,video_url=?,publie=? WHERE id=?');$q->execute([$title,$desc,$type,$media,$file,$media==='youtube'?$url:null,$published,$id]);$notice='Contenu modifié.';}else{$q=$pdo->prepare('INSERT INTO contenus(titre,description,type,media_type,fichier,video_url,publie) VALUES(?,?,?,?,?,?,?)');$q->execute([$title,$desc,$type,$media,$file,$media==='youtube'?$url:null,$published]);$notice='Contenu publié/enregistré.';}}
 elseif($action==='delete'){ $id=(int)$_POST['id'];$q=$pdo->prepare('SELECT fichier FROM contenus WHERE id=?');$q->execute([$id]);$row=$q->fetch();if($row){$pdo->prepare('DELETE FROM contenus WHERE id=?')->execute([$id]);if($row['fichier'] && is_file(__DIR__.'/../'.$row['fichier']))unlink(__DIR__.'/../'.$row['fichier']);}$notice='Contenu supprimé.';}
 elseif($action==='toggle'){ $pdo->prepare('UPDATE contenus SET publie=1-publie WHERE id=?')->execute([(int)$_POST['id']]);$notice='Visibilité mise à jour.';}
 }catch(Throwable $ex){$error=$ex->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM contenus WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$items=$pdo->query('SELECT * FROM contenus ORDER BY created_at DESC')->fetchAll();$counts=$pdo->query('SELECT type,COUNT(*) total FROM contenus GROUP BY type')->fetchAll();
