<section class="admin-card"><h2><?= $edit?'Modifier le contenu':'Ajouter une publicité ou une vidéo' ?></h2><form class="admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><label>Titre<input name="titre" required maxlength="180" value="<?=e($edit['titre']??'')?>"></label><label>Catégorie<select name="type"><?php foreach(['publicite'=>'Publicité','bande_annonce'=>'Bande-annonce','actualite'=>'Actualité'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['type']??'publicite')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Type de média<select name="media_type" id="mediaType"><?php foreach(['image'=>'Image (JPG/PNG/WEBP)','video'=>'Vidéo (MP4/WEBM)','youtube'=>'Lien YouTube'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['media_type']??'image')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Fichier média (facultatif si modification)<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label><label class="wide">URL YouTube (si média YouTube)<input type="url" name="video_url" placeholder="https://www.youtube.com/watch?v=..." value="<?=e($edit['video_url']??'')?>"></label><label class="wide">Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label><span><input type="checkbox" name="publie" value="1" <?=(!isset($edit['publie'])||$edit['publie'])?'checked':''?>> Publier immédiatement</span></label><div class="wide admin-actions"><button class="admin-btn" type="submit"><?= $edit?'Enregistrer les modifications':'Ajouter le contenu' ?></button><?php if($edit):?><a class="secondary" href="dashboard.php">Annuler</a><?php endif;?></div></form><p style="color:#999;font-size:12px">Formats autorisés : JPG, PNG, WEBP, MP4, WEBM. Taille maximale : 50 Mo. Pour les longues bandes-annonces, privilégiez YouTube.</p></section>
<section class="admin-card"><h2>Contenus enregistrés (<?=count($items)?>)</h2><table class="admin-table"><thead><tr><th>Titre</th><th>Type</th><th>Visibilité</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['titre'])?></td><td><?=e($it['type'])?></td><td><?=$it['publie']?'Publié':'Masqué'?></td><td><?=date('d/m/Y',strtotime($it['created_at']))?></td><td><div class="admin-actions"><a class="secondary" href="?edit=<?=$it['id']?>">Modifier</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$it['id']?>"><button class="secondary">Masquer / publier</button></form><form method="post" onsubmit="return confirm('Supprimer ce contenu ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$it['id']?>"><button class="danger">Supprimer</button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Aucun contenu pour le moment.</td></tr><?php endif;?></tbody></table></section></main></body></html>
